        },
        {
          "evidence_id": "E0011",
          "reason": "Conventional Syria/Iraq strike reporting is better treated as 2B escalation evidence; in 1B it is only indirect context."
        },
        {
          "evidence_id": "E0012",
          "reason": "Land-operation rhetoric is conventional-security escalation, not direct nuclear or existential-risk conduct."
        },
        {
          "evidence_id": "E0013",
          "reason": "2022 NATO Strategic Concept is alliance context, not Turkey-specific target-year conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct 2022 evidence of Erdoğan-specific nuclear rhetoric, doctrine change, command-and-control reform, or custody/safety decision.",
          "lenses": [
            "1B.2",
            "1B.3",
            "1B.4",
            "1B.7"
          ],
          "best_source_or_query_direction": "Turkish-language official records, NATO/NPG records, declassified or contemporaneous reporting on Incirlik and nuclear consultation, and Erdoğan statements on nuclear policy.",
          "why_it_matters": "The current file is mostly alliance or inherited context, so it cannot cleanly distinguish direct risk-bearing choice from background posture."
        }
      ],
      "reason": "The package is usable but thin on direct 2022 nuclear/existential-risk choices by Erdoğan; much of the supporting material is inherited or alliance-level context, while the stronger 2022 items are indirect de-escalation and conventional-security episodes."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Independent verification of civilian harm and decision-chain details for the late-2022 Syria/Iraq strikes is still limited.",
          "lenses": [
            "2B.4",
            "2B.5",
            "2B.9"
          ],
          "best_source_or_query_direction": "UN/ICRC/rights investigations, Turkish parliamentary or operational records, and contemporaneous Turkish-language reporting on the November 2022 strikes.",
          "why_it_matters": "The package shows the mixed peace/coercion record, but better command and casualty evidence would sharpen attribution and proportionality."
        }
      ],
      "reason": "The package fairly presents both the positive mediation record and the adverse escalation record, preserves contrary evidence, and keeps attribution appropriately mixed between Erdoğan, the state, and multilateral partners."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Direct command-chain evidence tying protest, custody, and detention abuses to presidential direction remains thin.",
          "lenses": [
            "3B.2",
            "3B.4",
            "3B.5",
            "3B.8"
          ],
          "best_source_or_query_direction": "Court files, ministry records, parliamentary inquiries, and independent domestic investigations into police/prosecutorial conduct in 2022.",
          "why_it_matters": "The current file shows serious domestic-safety failures, but attribution is often institutional rather than command-specific."
        }
      ],
      "reason": "The package presents a credible adverse record on custody abuse, domestic-violence protection failure, and protest repression while preserving the corrective statute and distinguishing allegations from findings."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "A direct 2022 succession or term-limit stress test is absent, so 4B.8 remains structural rather than event-based.",
          "lenses": [
            "4B.8",
            "4B.4"
          ],
          "best_source_or_query_direction": "Election-board appointment records, constitutional-court material, ODIHR/Venice Commission opinions, and party/legislative records from the 2022 electoral-law process.",
          "why_it_matters": "It would tighten the distinction between general authoritarian structure and a ruler-specific entrenchment choice."
        }
      ],
      "reason": "The file fairly shows democratic backsliding, media capture, electoral-law manipulation, and opposition pressure, with no major mismatch between the evidence and the chapter frame."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0053",
          "reason": "Broad Transparency International country context is not year-specific or ruler-specific enough to drive the 2022 economic assessment."
        },
        {
          "evidence_id": "E0057",
          "reason": "This is partly prospective green-growth framing and should remain context unless paired with stronger 2022 implementation evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Project-level completion and household welfare attribution remain thin relative to the macro policy evidence.",
          "lenses": [
            "5B.6",
            "5B.8",
            "5B.10"
          ],
          "best_source_or_query_direction": "Budget execution records, procurement audits, Turkish Statistical Institute distributional series, and IMF technical annexes.",
          "why_it_matters": "The package shows policy direction and macro outcomes, but less of the direct implementation chain and household-level effect."
        }
      ],
      "reason": "The economic package is balanced and credible on the low-rate inflation spiral, targeted relief, and countervailing growth figures; the main weakness is attribution and confounding, not fairness of presentation."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Housing, sanitation, and school-quality evidence is underrepresented compared with health and refugee-cash-transfer evidence.",
          "lenses": [
            "6B.2",
            "6B.3",
            "6B.9"
          ],
          "best_source_or_query_direction": "Turkish ministry execution data, UNESCO/WHO/UNICEF service series, and independent program evaluations for 2022.",
          "why_it_matters": "The package is fair, but a broader service mix would make the welfare judgment less dependent on donor-partner programs."
        }
      ],
      "reason": "The file fairly separates baseline welfare strengths from 2022 stressors and includes both supportive and adverse evidence, though it leans heavily on health and refugee-transfer material."
    },
    {
      "chapter_id": "7B",
