          "reason": "Reuters Institute media-environment reporting is useful context, but it is country-level pressure, not direct evidence of Erdoğan's personal honesty."
        },
        {
          "evidence_id": "E0076",
          "reason": "This is political rhetoric and an interpretive claim about motive, not proof of deception or self-dealing."
        },
        {
          "evidence_id": "E0077",
          "reason": "The allegation trail touches the family network, but Erdoğan's own awareness or benefit is not independently confirmed."
        },
        {
          "evidence_id": "E0078",
          "reason": "This is a family-network lawsuit and contested accusation, not proven personal misconduct by Erdoğan."
        },
        {
          "evidence_id": "E0079",
          "reason": "The complaint concerns a family-linked business dispute, but it does not independently establish Erdoğan's personal self-dealing."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct primary evidence on Erdoğan's own assets, gifts, procurement benefits, or acknowledged falsehood correction in 2022 is still missing.",
          "lenses": [
            "7B.3",
            "7B.4",
            "7B.2",
            "7B.6"
          ],
          "best_source_or_query_direction": "Asset declarations, procurement records, court findings, anti-corruption investigations, and full-text investigative reporting with documentary support.",
          "why_it_matters": "This chapter requires a personal-nexus finding, and the current package is stronger on environment and family-network pressure than on proven Erdoğan self-enrichment."
        }
      ],
      "reason": "The integrity file is directionally useful but still needs follow-up because several of the most pointed items are family-network allegations or media-environment context rather than independently proven Erdoğan personal conduct."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Project-level completion and internal monitoring evidence is thinner than the program-and-allocation evidence.",
          "lenses": [
            "8B.2",
            "8B.6",
            "8B.7",
            "8B.8"
          ],
          "best_source_or_query_direction": "Ministry implementation reports, audit findings, project completion data, CBRT records, and independent evaluations.",
          "why_it_matters": "The package shows declared program, execution intent, and some outcomes, but less proof of day-to-day follow-through."
        }
      ],
      "reason": "The competence record fairly separates declared programs, implementation, outcomes, and confounders; the main limitation is incomplete proof of project-level execution, not package bias."
    }
  ]
